#include "profile_library.h"
#include <windows.h>
#include <algorithm>
#include <atomic>
#include <cmath>
#include <cstdio>
#include <filesystem>
#include <regex>
#include <stdexcept>
namespace druta::ui {
namespace {
namespace fs=std::filesystem;
void require(bool b,const char* message){if(!b)throw std::runtime_error(message);}
std::string utf8(const std::wstring& s){if(s.empty())return {};require(s.size()<=32768,"Profile path too long");int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),static_cast<int>(s.size()),nullptr,0,nullptr,nullptr);require(n>0,"Profile path Unicode invalid");std::string out(static_cast<size_t>(n),0);require(WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),static_cast<int>(s.size()),out.data(),n,nullptr,nullptr)==n,"Profile path conversion failed");return out;}
std::wstring env(const wchar_t* name){DWORD n=GetEnvironmentVariableW(name,nullptr,0);if(!n||n>32768)return {};std::wstring out(n,0);DWORD got=GetEnvironmentVariableW(name,out.data(),n);if(!got||got>=n)return {};out.resize(got);return out;}
std::wstring executable(){std::wstring path(32768,0);const auto n=GetModuleFileNameW(nullptr,path.data(),static_cast<DWORD>(path.size()));require(n&&n<path.size(),"Cannot resolve profile executable directory");path.resize(n);return path;}
fs::path absolute(const std::wstring& path){require(!path.empty()&&path.find(L'\0')==std::wstring::npos,"Profile directory invalid");return fs::absolute(path).lexically_normal();}
std::wstring fold(std::wstring value){for(auto& c:value)if(c>=L'A'&&c<=L'Z')c=static_cast<wchar_t>(c+L'a'-L'A');return value;}
std::string slug(const std::string& value){std::string out;bool dash=false;for(unsigned char c:value){const bool safe=(c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='.'||c=='_'||c=='-';if(safe){out+=static_cast<char>(c);dash=false;}else if(!dash){out+='-';dash=true;}}const auto first=out.find_first_not_of('-');if(first==std::string::npos)return "unnamed";out=out.substr(first);while(!out.empty()&&out.back()=='-')out.pop_back();if(out.size()>100)out.resize(100);return out.empty()?"unnamed":out;}
bool is_owned(const std::wstring& name){static const std::wregex re(L"^autosave-native-.+-[0-9a-f]{16}-[0-9a-f]{8}-[0-9a-f]{8}\\.json$");return std::regex_match(name,re);}
uint64_t file_time(const fs::path& path){WIN32_FILE_ATTRIBUTE_DATA info{};require(GetFileAttributesExW(path.c_str(),GetFileExInfoStandard,&info)!=0,"Profile file timestamp unavailable");ULARGE_INTEGER t{};t.LowPart=info.ftLastWriteTime.dwLowDateTime;t.HighPart=info.ftLastWriteTime.dwHighDateTime;return t.QuadPart;}
double seconds(uint64_t t){constexpr uint64_t epoch=116444736000000000ull;return t>=epoch?double(t-epoch)/10000000.0:-double(epoch-t)/10000000.0;}
std::string display_time(uint64_t ticks){FILETIME utc{static_cast<DWORD>(ticks),static_cast<DWORD>(ticks>>32)},local{};SYSTEMTIME value{};require(FileTimeToLocalFileTime(&utc,&local)!=0&&FileTimeToSystemTime(&local,&value)!=0,"Profile display timestamp unavailable");char text[32]{};std::snprintf(text,sizeof(text),"%04u-%02u-%02u %02u:%02u:%02u",unsigned(value.wYear),unsigned(value.wMonth),unsigned(value.wDay),unsigned(value.wHour),unsigned(value.wMinute),unsigned(value.wSecond));return text;}std::wstring native_root(const ProfileLibraryDirectory& native){require(native.writable,"Only the native profile library may be written");return absolute(native.path).wstring();}
void prune(const ProfileLibraryDirectory& native){const auto root=native_root(native);std::vector<std::pair<uint64_t,fs::path>> autos;for(const auto& file:fs::directory_iterator(root))if(file.is_regular_file()&&is_owned(file.path().filename().wstring()))autos.emplace_back(file_time(file.path()),file.path());std::sort(autos.begin(),autos.end(),[](const auto& a,const auto& b){return a.first!=b.first?a.first>b.first:a.second.filename()>b.second.filename();});for(size_t i=20;i<autos.size();++i){std::error_code ignored;fs::remove(autos[i].second,ignored);}}
}
std::vector<ProfileLibraryDirectory> discover_profile_directories(const ProfileLibraryPaths& paths){std::vector<ProfileLibraryDirectory> out;const auto exe=absolute(paths.executable.empty()?executable():paths.executable);auto local=paths.local_app_data.empty()?env(L"LOCALAPPDATA"):paths.local_app_data;if(local.empty())local=env(L"USERPROFILE");require(!local.empty(),"Profile user storage unavailable");
 const auto add=[&](const fs::path& path,const char* source,bool writable){const auto canonical=absolute(path.wstring());std::error_code ec;if(!writable&&!fs::is_directory(canonical,ec))return;for(const auto& existing:out)if(fold(existing.path)==fold(canonical.wstring()))return;out.push_back({canonical.wstring(),source,writable});};
 add(absolute(local)/L"Druta"/L"profiles","Native",true);auto ancestor=exe.parent_path();for(;;){std::error_code ec;if(fs::is_regular_file(ancestor/L"pyproject.toml",ec)&&fs::is_directory(ancestor/L"src"/L"druta",ec)){add(ancestor/L"profiles","Python source",false);break;}const auto parent=ancestor.parent_path();if(parent==ancestor||parent.empty())break;ancestor=parent;}
 add(exe.parent_path()/L"profiles","Portable",false);add(absolute(local)/L"Thermetery"/L"Druta"/L"profiles","Python user",false);return out;}
std::vector<ProfileLibraryEntry> list_profile_library(const std::vector<ProfileLibraryDirectory>& directories){std::vector<ProfileLibraryEntry> out;std::vector<std::wstring> seen;for(const auto& directory:directories){const auto root=absolute(directory.path);std::error_code ec;if(!fs::exists(root,ec)){if(!ec)continue;}fs::directory_iterator files(root,ec);if(ec){ProfileLibraryEntry error;error.id=utf8(root.wstring());error.path=root.wstring();error.source=directory.source;error.name="Directory unavailable";error.error=ec.message();out.push_back(std::move(error));continue;}
 for(const auto& file:files){if(fold(file.path().extension().wstring())!=L".json"||!file.is_regular_file(ec))continue;const auto path=absolute(file.path().wstring());const auto key=fold(path.wstring());if(std::find(seen.begin(),seen.end(),key)!=seen.end())continue;seen.push_back(key);ProfileLibraryEntry entry;entry.path=path.wstring();entry.id=utf8(key);entry.name=utf8(path.stem().wstring());entry.source=directory.source;entry.autosave=entry.name.rfind("autosave-",0)==0;entry.library_owned=directory.writable&&is_owned(path.filename().wstring());try{const auto ticks=file_time(path);entry.timestamp=seconds(ticks);entry.saved_at=display_time(ticks);}catch(const std::exception& e){entry.error=e.what();}
 try{auto document=read_profile(entry.path);if(document.contains("saved_at")&&document["saved_at"].is_string()&&!document["saved_at"].get_ref<const std::string&>().empty())entry.saved_at=document["saved_at"].get<std::string>();if(document.contains("saved_ts")&&document["saved_ts"].is_number()){const auto ts=document["saved_ts"].get<double>();if(std::isfinite(ts))entry.timestamp=ts;}entry.document=std::move(document);}catch(const std::exception& e){entry.error=e.what();}out.push_back(std::move(entry));}}
 std::sort(out.begin(),out.end(),[](const auto& a,const auto& b){if(a.timestamp!=b.timestamp)return a.timestamp>b.timestamp;if(a.saved_at!=b.saved_at)return a.saved_at>b.saved_at;return a.id>b.id;});return out;}
std::wstring profile_library_named_path(const ProfileLibraryDirectory& native,const std::string& name){const auto safe=slug(name);require(safe.rfind("autosave-",0)!=0,"The autosave- prefix is reserved for history; choose a profile name");const auto root=native_root(native);fs::create_directories(root);return (fs::path(root)/fs::path(safe+".json")).wstring();}
std::wstring save_library_profile(const ProfileLibraryDirectory& native,const std::string& name,const ProfileJson& document){const auto path=profile_library_named_path(native,name);write_profile(path,document);return path;}
std::wstring save_library_autosave(const ProfileLibraryDirectory& native,const std::string& action,const ProfileJson& document){static std::atomic<uint32_t> serial{0};const auto root=native_root(native);fs::create_directories(root);std::wstring path;for(unsigned attempt=0;attempt<32;++attempt){FILETIME time{};GetSystemTimeAsFileTime(&time);char suffix[64]{};std::snprintf(suffix,sizeof(suffix),"-%08x%08x-%08x-%08x.json",static_cast<unsigned>(time.dwHighDateTime),static_cast<unsigned>(time.dwLowDateTime),static_cast<unsigned>(GetCurrentProcessId()),static_cast<unsigned>(serial.fetch_add(1)));const auto name="autosave-native-"+slug(action)+suffix;path=(fs::path(root)/name).wstring();HANDLE file=CreateFileW(path.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(file==INVALID_HANDLE_VALUE){const auto e=GetLastError();if(e==ERROR_FILE_EXISTS||e==ERROR_ALREADY_EXISTS)continue;throw std::runtime_error("Cannot reserve profile history filename (Windows error "+std::to_string(e)+")");}CloseHandle(file);try{write_profile(path,document);}catch(...){DeleteFileW(path.c_str());throw;}prune(native);return path;}throw std::runtime_error("Cannot reserve a unique profile history filename");}
}
